// Helper function to extract variables from prompt text
const extractVariables = (text: string): string[] => {
  const regex = /\{\{\s*(\w+)\s*\}\}/g;
  const matches = text.matchAll(regex);
  return [...new Set(Array.from(matches, m => m[1]))];
};

